cat > $D/try.mjs <<'EOF'
import { load, B } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";
const [,, src, out, ...spots] = process.argv;
const g = load(src);
for (const s of spots) { const [x, y, z, hang] = s.split(",").map(Number); g.set(x, y, z, ...B.lantern(hang === 1)); }
g.save(out);
EOF
MCD=/Volumes/ext1/swe/repos/minecraft-design/tools/bin/mcd.mjs
for case in "35,4,55,0" "36,9,55,1 36,9,59,1 36,9,57,1" ; do
